#include "ReferenceComparison.h"
static void testReferenceComparison(const File& root,Assets& assets){
    ReferenceReport report;report.mix.peak={.8,.8};report.reference.peak={.2,.2};report.mix.rms={.4,.4};report.reference.rms={.1,.1};auto gains=referenceGains(report,true);
    expect(std::abs(gains[0]-.175f)<1e-7&&std::abs(gains[1]-.7f)<1e-7,"RMS matching attenuates only the louder side and retains common audition gain");expect(std::abs(report.mix.rms[0]*gains[0]-report.reference.rms[0]*gains[1])<1e-8,"level matched stereo RMS is equal");
    auto raw=referenceGains(report,false);expect(raw[0]==.7f&&raw[1]==.7f,"original-relative mode uses identical gains for both sides");report.reference.peak={4,4};auto hot=referenceGains(report,false);expect(std::abs(hot[0]-.245f)<1e-7&&hot[0]==hot[1]&&4*hot[1]<=.980001,"hot float references receive common anti-clipping attenuation without normalization");report.mix.rms={0,0};auto silent=referenceGains(report,true);expect(silent==hot,"one silent passage disables RMS matching without division by zero");
    expect(validateReferenceOptions({0,0,.25}).wasOk()&&validateReferenceOptions({8192,86400,60}).wasOk(),"comparison range limits accept exact finite boundaries");
    expect(validateReferenceOptions({-1,0,1}).failed()&&validateReferenceOptions({0,-1,1}).failed()&&validateReferenceOptions({0,0,61}).failed()&&validateReferenceOptions({0,0,.24}).failed()&&validateReferenceOptions({0,0,std::numeric_limits<double>::quiet_NaN()}).failed(),"invalid or nonfinite passage values fail before work begins");
    auto folder=root.getChildFile("reference-core");folder.createDirectory();auto reference=folder.getChildFile("original.wav");reference.deleteFile();AudioBuffer<float> original(2,96000);for(int i=0;i<96000;++i){float tone=.2f*(float)std::sin(2*MathConstants<double>::pi*1000*i/48000.);original.setSample(0,i,tone);original.setSample(1,i,-tone);}auto stream=reference.createOutputStream();WavAudioFormat format;auto writer=std::unique_ptr<AudioFormatWriter>(stream?format.createWriterFor(stream.get(),48000,2,24,{},0):nullptr);expect(writer!=nullptr,"create reference comparison fixture");if(!writer)return;stream.release();writer->writeFromAudioSampleBuffer(original,0,96000);writer.reset();auto hash=SHA256(reference).toHexString();
    auto song=emptyProject();song.bpm=120;song.patterns[0].lanes[7]={{0,4,60,.7f}};ReferenceOptions options{1,.5,1};auto target=folder.getChildFile(Uuid().toString());std::atomic<bool> cancel{false};std::atomic<float> progress{0};
    expect(compareReference(song,root,reference,options,target,report,&cancel,&progress).wasOk(),"worker compares an exact current Pattern passage to selected reference audio");
    expect(report.mix.frames==48000&&report.reference.frames==48000&&report.options==options&&progress.load()==1,"both comparison snapshots have matching duration and 48 kHz frame count");
    expect(report.reference.correlationValid&&report.reference.correlation<-.999999&&report.reference.bandFraction[1]>.999,"reference stereo polarity and calibrated 1 kHz FFT band are retained");
    expect(std::abs(report.reference.rms[0]-.2/std::sqrt(2.))<1e-6&&std::abs(report.reference.peak[0]-.2)<1e-6,"reference report measurements match calibrated decoded source values");
    String error;auto* a=assets.load(report.mixFile,error);auto* b=assets.load(report.referenceCopy,error);expect(a&&b&&a->audio.getNumSamples()==48000&&b->audio.getNumSamples()==48000,"both float32 snapshots are playable without changing source files");
    RenderSettings settings;settings.bits=32;settings.startBeat=1;settings.endBeat=3;settings.tailSeconds=0;auto exported=folder.getChildFile("normal-export.wav");expect(renderAudio(song,assets,root,exported,settings).wasOk(),"comparison export fixture is available");
    expect(SHA256(exported).toHexString()==SHA256(report.mixFile).toHexString(),"mix snapshot is byte-identical to the ordinary project-only export path");
    expect(SHA256(reference).toHexString()==hash&&report.referenceHash==hash&&report.projectHash==mixProjectHash(song,root),"comparison records verified source/project identities and never changes original audio");
    auto json=referenceToJson(report);expect((int)json["schema"]==1&&(int)json["sampleRate"]==48000&&(int64)json["mix"]["frames"]==48000&&json["summary"].toString().contains("not LUFS"),"comparison JSON and readable report identify units and measurement limits");
    auto saved=folder.getChildFile("report.json");expect(saveReferenceReport(saved,report).wasOk()&&JSON::parse(saved)["referenceHash"].toString()==hash,"measured comparison persists separately from the musical project");auto retained=saved.loadFileAsString();auto invalid=report;invalid.mix.rms[0]=std::numeric_limits<double>::infinity();expect(saveReferenceReport(saved,invalid).failed()&&saved.loadFileAsString()==retained,"invalid comparison report cannot replace existing saved evidence");
    auto previous=referenceSummary(report);auto rejected=folder.getChildFile(Uuid().toString());cancel.store(true);expect(compareReference(song,root,reference,options,rejected,report,&cancel).failed()&&!rejected.exists()&&referenceSummary(report)==previous,"pre-cancelled worker commits no files or report changes");cancel.store(false);
    expect(compareReference(song,root,reference,{0,1.8,1},rejected,report).failed()&&!rejected.exists()&&referenceSummary(report)==previous,"reference overrun fails atomically before creating audition files");
    expect(compareReference(song,root,reference,{7,0,1},rejected,report).failed()&&!rejected.exists(),"mix overrun cannot create a misleading partial comparison");
    expect(compareReference(song,root,reference,options,target,report).failed()&&report.mixFile.existsAsFile(),"existing output folders are never overwritten or cleaned by a new worker");
    // A differently sampled mono source is decoded only for the chosen excerpt.
    auto mono=folder.getChildFile("mono-44100.wav");mono.deleteFile();AudioBuffer<float> signal(1,88200);for(int i=0;i<88200;++i)signal.setSample(0,i,.1f);auto out=mono.createOutputStream();auto monoWriter=std::unique_ptr<AudioFormatWriter>(out?format.createWriterFor(out.get(),44100,1,24,{},0):nullptr);expect(monoWriter!=nullptr,"create mono 44.1 kHz comparison source");if(monoWriter){out.release();monoWriter->writeFromAudioSampleBuffer(signal,0,88200);monoWriter.reset();ReferenceReport converted;expect(compareReference(song,root,mono,{0,.25,.5},folder.getChildFile(Uuid().toString()),converted).wasOk()&&converted.reference.frames==24000&&std::abs(converted.reference.rms[0]-.1)<1e-5&&converted.reference.rms[0]==converted.reference.rms[1],"mono 44.1 kHz excerpts convert to equal-duration 48 kHz stereo before comparison");}
}
